function estimateReadMinutes(item) {
  if (!item || !Array.isArray(item.parts)) return 3;
  const words = item.parts.join(' ').replace(/<[^>]*>/g, ' ').trim().split(/\s+/).length;
  return Math.max(2, Math.round(words / 210));
}

const ARTICLES_LIST = Object.keys(ARTICLE_CARD_META).map((id) => {
  const meta = ARTICLE_CARD_META[id];
  const data = ARTICLE_DATA[id] || {};
  return {
    id,
    slug: id,
    status: HIDDEN_ARTICLE_IDS.has(id) ? 'hidden_pending_review' : 'published',
    featured: FEATURED_ARTICLE_IDS.includes(id),
    category: meta.category,
    tag: meta.tag,
    meta: meta.meta,
    cardTitle: meta.cardTitle || data.title || '',
    summary: meta.summary || '',
    thumb: meta.thumb || data.image || '',
    thumbAlt: meta.thumbAlt || data.imageAlt || meta.cardTitle || '',
    readMinutes: estimateReadMinutes(data),
    topic: data.topic || meta.tag
  };
});
